const PYTHON_STYLE_INT_PATTERN = /^[+-]?\d(?:_?\d)*$/;
const NEGATIVE_INTEGER_TOKEN_PATTERN = /^-\d(?:_?\d)*$/;

export function isPythonStyleIntText(rawValue) {
  return PYTHON_STYLE_INT_PATTERN.test(rawValue);
}

export function looksLikeNegativeIntegerToken(rawValue) {
  return NEGATIVE_INTEGER_TOKEN_PATTERN.test(rawValue);
}

export function normalizePythonStyleInt(rawValue) {
  if (!isPythonStyleIntText(rawValue)) {
    return null;
  }

  let normalizedSign = '';
  let digits = rawValue;

  if (digits.startsWith('+') || digits.startsWith('-')) {
    normalizedSign = digits[0] === '-' ? '-' : '';
    digits = digits.slice(1);
  }

  const compactDigits = digits.replace(/_/g, '');
  return BigInt(`${normalizedSign}${compactDigits}`).toString();
}

export function normalizeStoredInteger(rawValue) {
  return BigInt(String(rawValue)).toString();
}

