import { normalizeStoredInteger } from './integer_text.mjs';

const hasOwn = Object.prototype.hasOwnProperty;

export function createBidirectionalLookup(entries) {
  const forward = Object.create(null);
  const inverse = Object.create(null);

  for (const [key, value] of entries) {
    const normalizedValue = normalizeStoredInteger(value);

    if (hasOwn.call(forward, key)) {
      throw new Error(`Duplicate key: ${key}`);
    }

    if (hasOwn.call(inverse, normalizedValue)) {
      throw new Error(`Duplicate value: ${value}`);
    }

    forward[key] = normalizedValue;
    inverse[normalizedValue] = key;
  }

  return {
    hasKey(key) {
      return hasOwn.call(forward, key);
    },
    hasValue(normalizedValue) {
      return hasOwn.call(inverse, normalizedValue);
    },
  };
}

